package com.motionstudio.part6
import java.io.File
import java.security.MessageDigest
import java.util.concurrent.atomic.AtomicLong
data class RecoveryState(val projectId:String,val projectVersion:Int,val savedAt:Long,val sourceHash:String,val complete:Boolean,val file:File)
class RecoveryEngine(private val root:File){init{root.mkdirs()};fun writeAutosave(projectId:String,version:Int,source:ByteArray):RecoveryState{val hash=sha(source);val dir=File(root,projectId);dir.mkdirs();val f=File(dir,"autosave-$version.tmp");f.writeBytes(source);val final=File(dir,"autosave-$version.project");require(f.renameTo(final));return RecoveryState(projectId,version,System.currentTimeMillis(),hash,true,final)};fun latest(projectId:String):RecoveryState?{val dir=File(root,projectId);return dir.listFiles()?.filter{it.name.startsWith("autosave-")&&it.extension=="project"}?.maxByOrNull{it.lastModified()}?.let{RecoveryState(projectId,0,it.lastModified(),sha(it.readBytes()),true,it)}};fun backup(projectId:String,project:File):File{require(project.isFile);val dir=File(root,projectId);dir.mkdirs();val b=File(dir,"backup-${System.currentTimeMillis()}.project");project.copyTo(b,overwrite=false);return b};fun isValid(project:File,validator:(ByteArray)->Boolean)=project.isFile&&runCatching{validator(project.readBytes())}.getOrDefault(false);fun recoverSafely(candidate:File,destination:File,validator:(ByteArray)->Boolean):Boolean{if(!isValid(candidate,validator))return false;val tmp=File(destination.parentFile,destination.name+".recovery");candidate.copyTo(tmp,overwrite=true);if(!validator(tmp.readBytes())){tmp.delete();return false};if(destination.isFile){val backup=File(destination.parentFile,destination.name+".pre-recovery");destination.copyTo(backup,overwrite=false)};require(tmp.renameTo(destination));return true};private fun sha(b:ByteArray)=MessageDigest.getInstance("SHA-256").digest(b).joinToString(""){"%02x".format(it)}}
